// ❌ OLD (as a pattern to avoid): manually tracking cleanup. In a
// language without RAII you'd have to remember to close the file,
// free the buffer, and unlock the mutex on EVERY exit path. In Rust,
// the default is automatic — the Drop impl runs at scope end.
fn read_first_line(path: &str) -> std::io::Result<String> {
    let file = std::fs::File::open(path)?;
    // ✅ (the correct pattern) drop(file) is automatic at scope end.
    // ❌ The WRONG instinct is to try to 'manually close' and forget
    // that the borrow checker + Drop already handle it.
    let mut buf = String::new();
    // std::io::BufReader::new(file) would take ownership...
    Ok(buf)
}

// Key insight: you don't write cleanup; Drop does it for you.

use std::mem::ManuallyDrop;

// ✅ NEW: ManuallyDrop stops the automatic drop of the wrapped value.
// Use it when ownership is transferred to non-Rust code (FFI) or when
// you must control the exact cleanup moment.
struct FfiBox(*mut u8); // a raw pointer whose memory the C side owns

fn give_to_c(v: FfiBox) {
    let md = ManuallyDrop::new(v); // ✅ NEW: no auto-drop of the pointer
    unsafe {
        // hand the pointer to C; C will free it
        ffi_take_ownership(md.0);
    }
    // ✅ NEW: when md goes out of scope, the inner FfiBox is NOT
    // dropped — no double-free, no premature free.
}

